// src/components/AdminStudentsFees.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import "../styles/main.css";

/**
 * Admin UI to manage per-student fee overrides and student-only fee types (Option A)
 *
 * Behavior:
 * - Shows list of students (GET /api/fees/admin/students)
 * - When a student is selected it loads computed fee info (GET /api/fees/student/:admissionNo)
 * - Admin can:
 *    - edit amounts for class-based heads (only the selected student's overrides)
 *    - add a student-only fee type (key + title + amount) — stored as an object under student's feeOverrides
 *    - delete a student-only fee type (only from this student)
 * - Save persists to backend via POST /api/fees/student { admissionNo, feeOverrides }
 *
 * NOTE: server should store feeOverrides either as:
 *  { tuition: 25000, transport: 5000, dance: { amount: 1200, title: "Dance Class" } }
 *  and GET /api/fees/student should merge these into returned fee.items (see backend snippet).
 */

export default function AdminStudentsFees() {
  const [students, setStudents] = useState([]);
  const [selected, setSelected] = useState(null);
  const [feeStructure, setFeeStructure] = useState(null); // global fee structure
  const [overrides, setOverrides] = useState({}); // key -> number or {amount, title}
  const [paid, setPaid] = useState(0);
  const [total, setTotal] = useState(0);
  const [remaining, setRemaining] = useState(0);
  const [loading, setLoading] = useState(false);

  // Helper: returns class-based keys for a class number
  const getFeeKeysForClass = (cls) => {
    const c = Number(cls);
    if (c >= 1 && c <= 5) return ["development", "transport"];
    if (c >= 6 && c <= 9) return ["tuition", "development", "transport"];
    return ["exam", "tuition", "development"];
  };

  useEffect(() => {
    fetchStudents();
    fetchFeeStructure();
  }, []);

  const fetchStudents = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/fees/admin/students");
      setStudents(res.data.data || []);
    } catch (err) {
      console.error(err);
      toast.error("Failed to load students");
    }
  };

  const fetchFeeStructure = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/fees");
      if (res.data && res.data.data) setFeeStructure(res.data.data);
    } catch (err) {
      console.error(err);
    }
  };

  // select a student and load their computed fee & payments
  const selectStudent = async (stu) => {
    setSelected(stu);
    setOverrides({});
    setPaid(0);
    setTotal(0);
    setRemaining(0);

    try {
      const res = await axios.get(`http://localhost:5000/api/fees/student/${stu.admissionNo}`);
      if (!res.data.success) {
        toast.error("Failed to load student fee");
        return;
      }
      const payload = res.data.data; // contains student, fee.items, payments
      const student = payload.student || {};
      const items = payload.fee?.items || {};
      const payments = payload.payments || [];

      // Determine class keys
      const keys = getFeeKeysForClass(student.classApplied || student.class);

      // Build overrides starting from feeStructure amounts and student-specific overrides returned by server
      // The API returns fee.items merged with student overrides (see backend change). But we also want to preserve student-only extra keys.
      const newOverrides = {};

      // Ensure feeStructure present
      const fsItems = feeStructure?.items || [];
      // create helper map of titles by key
      const titleMap = {};
      fsItems.forEach((it) => (titleMap[it.key] = it.title));

      // initialize overrides for class keys from returned items
      keys.forEach((k) => {
        const item = items[k];
        newOverrides[k] = item ? item.amount : 0;
      });

      // include any extra (student-only) keys that returned items contain but are not in class keys
      Object.keys(items).forEach((k) => {
        if (!newOverrides.hasOwnProperty(k)) {
          // if items[k] exists, it might be a student-only fee
          newOverrides[k] = items[k]?.amount ?? 0;
        }
      });

      // Save overrides to state
      setOverrides(newOverrides);

      // compute totals
      const totalAmt = Object.values(newOverrides).reduce((s, v) => s + (Number(v) || 0), 0);
      const paidAmt = payments.reduce((s, t) => s + (t.amount || 0), 0);
      setTotal(totalAmt);
      setPaid(paidAmt);
      setRemaining(Math.max(0, totalAmt - paidAmt));
    } catch (err) {
      console.error(err);
      toast.error("Failed to load student fee details");
    }
  };

  const updateOverride = (key, value) => {
    const num = Number(value) || 0;
    setOverrides((prev) => {
      const updated = { ...prev, [key]: num };
      const tot = Object.values(updated).reduce((s, v) => s + Number(v || 0), 0);
      setTotal(tot);
      setRemaining(Math.max(0, tot - paid));
      return updated;
    });
  };

  // Add a student-only fee type (key + title + amount)
  const addFeeType = () => {
    const rawKey = prompt("Enter new fee type key (example: dance). Use lowercase no spaces:");
    if (!rawKey) return;
    const key = rawKey.trim();
    if (!/^[a-zA-Z0-9_-]+$/.test(key)) {
      return toast.error("Invalid key. Use letters/numbers/underscore/dash, no spaces.");
    }
    const title = prompt("Enter a display Title (e.g. Dance Class):") || key;
    const amountStr = prompt("Enter initial amount (number):", "0");
    const amount = Number(amountStr) || 0;

    // For student-specific extra head, we will save in overrides as a plain number.
    // Backend will store under student.feeOverrides[key] = { amount, title } to preserve title too.
    // But here on client keep a simple numeric override; server will accept an object as value (we'll send {amount, title}).
    // Add to overrides immediately
    setOverrides((prev) => {
      if (prev.hasOwnProperty(key)) {
        toast.error("Fee key already present for this student");
        return prev;
      }
      const updated = { ...prev, [key]: amount };
      const tot = Object.values(updated).reduce((s, v) => s + Number(v || 0), 0);
      setTotal(tot);
      setRemaining(Math.max(0, tot - paid));
      // Save meta in a temp structure? We'll send title along with save.
      // We'll store a transient meta map in state as well but to keep file simple we will prompt and attach when saving.
      // store temporarily in sessionStorage so save can pick it up:
      const meta = JSON.parse(sessionStorage.getItem("studentFeeMeta") || "{}");
      meta[key] = { title };
      sessionStorage.setItem("studentFeeMeta", JSON.stringify(meta));
      return updated;
    });
  };

  const deleteFeeType = (key) => {
    if (!window.confirm(`Delete fee type "${key}" for this student? (This will remove only for this student)`)) return;
    setOverrides((prev) => {
      const updated = { ...prev };
      delete updated[key];
      const tot = Object.values(updated).reduce((s, v) => s + Number(v || 0), 0);
      setTotal(tot);
      setRemaining(Math.max(0, tot - paid));
      // also remove meta
      const meta = JSON.parse(sessionStorage.getItem("studentFeeMeta") || "{}");
      delete meta[key];
      sessionStorage.setItem("studentFeeMeta", JSON.stringify(meta));
      return updated;
    });
  };

  // Save overrides to backend for selected student
  const saveChanges = async () => {
    if (!selected) return toast.error("Select a student first");
    setLoading(true);
    try {
      // Build feeOverrides payload: for student-specific keys that are new we want to save { amount, title }
      const meta = JSON.parse(sessionStorage.getItem("studentFeeMeta") || "{}");
      const payloadOverrides = {};
      Object.entries(overrides).forEach(([k, v]) => {
        if (meta[k]) {
          // student-specific: save as object to preserve title
          payloadOverrides[k] = { amount: Number(v || 0), title: meta[k].title || k };
        } else {
          // normal override (class-based) save as number
          payloadOverrides[k] = Number(v || 0);
        }
      });

      const res = await axios.post("http://localhost:5000/api/fees/student", {
        admissionNo: selected.admissionNo,
        feeOverrides: payloadOverrides,
      });

      if (res.data.success) {
        toast.success("Fee overrides saved for student");
        // cleanup meta for this student in sessionStorage (optional)
        sessionStorage.removeItem("studentFeeMeta");
        // reload student
        selectStudent(selected);
      } else {
        toast.error(res.data.error || "Failed to save");
      }
    } catch (err) {
      console.error(err);
      toast.error("Failed to save changes");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="admin-fees-page">
      <Toaster />
      <h2 style={{ color: "#003366", marginBottom: 8 }}>Manage Student Fees (student-specific overrides)</h2>
      <p>Choose a student, edit class-based amounts; add student-only heads if required. Save to persist per-student changes.</p>

      <div style={{ display: "flex", gap: 20 }}>
        {/* Student list */}
        <div style={{ width: 300, border: "1px solid #ddd", padding: 12, borderRadius: 6 }}>
          <h4>All Students</h4>
          <div style={{ maxHeight: 420, overflowY: "auto" }}>
            {students.length === 0 && <p>No students found</p>}
            <ul style={{ listStyle: "none", paddingLeft: 0 }}>
              {students.map((s) => (
                <li key={s._id}
                    onClick={() => selectStudent(s)}
                    style={{
                      padding: "8px 6px",
                      borderRadius: 4,
                      cursor: "pointer",
                      background: selected?._id === s._id ? "#eef" : "transparent",
                      marginBottom: 6
                    }}>
                  <b>{s.studentName}</b><br />
                  <small>{s.admissionNo} • Class {s.classApplied || s.class}</small>
                </li>
              ))}
            </ul>
          </div>
        </div>

        {/* Editor */}
        <div style={{ flex: 1, border: "1px solid #ddd", padding: 12, borderRadius: 6 }}>
          {!selected ? (
            <p>Select a student to edit fees.</p>
          ) : (
            <>
              <h3>{selected.studentName} — {selected.admissionNo} • Class {selected.classApplied || selected.class}</h3>

              <div style={{ marginBottom: 8 }}>
                <button onClick={addFeeType} style={{ marginRight: 8 }}>➕ Add Student-only Fee</button>
                <button onClick={saveChanges} disabled={loading}>{loading ? "Saving..." : "💾 Save Changes"}</button>
              </div>

              <table className="fee-table" style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr>
                    <th style={{ textAlign: "left", padding: 8, borderBottom: "1px solid #ddd" }}>Fee Type</th>
                    <th style={{ textAlign: "right", padding: 8, borderBottom: "1px solid #ddd" }}>Amount (₹)</th>
                    <th style={{ padding: 8, borderBottom: "1px solid #ddd" }}> </th>
                  </tr>
                </thead>
                <tbody>
                  {Object.entries(overrides).map(([k, val]) => (
                    <tr key={k}>
                      <td style={{ padding: 8, borderBottom: "1px solid #f0f0f0" }}>{k}</td>
                      <td style={{ padding: 8, borderBottom: "1px solid #f0f0f0", textAlign: "right" }}>
                        <input
                          type="number"
                          value={val}
                          onChange={(e) => updateOverride(k, e.target.value)}
                          style={{ width: 120, textAlign: "right" }}
                        />
                      </td>
                      <td style={{ padding: 8, borderBottom: "1px solid #f0f0f0", textAlign: "center" }}>
                        <button title="Delete this fee for the student" onClick={() => deleteFeeType(k)} style={{ background: "transparent", border: "none", cursor: "pointer", color: "#c0392b" }}>
                          🗑
                        </button>
                      </td>
                    </tr>
                  ))}

                  <tr>
                    <td style={{ padding: 8 }}><b>Total</b></td>
                    <td style={{ padding: 8, textAlign: "right" }}><b>₹{total.toLocaleString()}</b></td>
                    <td />
                  </tr>
                  <tr>
                    <td style={{ padding: 8 }}>Paid</td>
                    <td style={{ padding: 8, textAlign: "right" }}>₹{paid.toLocaleString()}</td>
                    <td />
                  </tr>
                  <tr>
                    <td style={{ padding: 8 }}>Remaining</td>
                    <td style={{ padding: 8, textAlign: "right" }}>₹{remaining.toLocaleString()}</td>
                    <td />
                  </tr>
                </tbody>
              </table>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
